import "dotenv/config";
import { randomUUID } from "node:crypto";
import { readdir, readFile } from "node:fs/promises";
import { Client } from "pg";

export const foundationMigration = "20261016010000_subscription_foundation";
export const databaseTestsEnabled = process.env.MAILLOOP_DB_TESTS === "1";

// Check before connecting or writing, including when helpers are used directly.
export function requireTestDatabaseUrl(value = process.env.DATABASE_URL) {
  if (!value) throw new Error("A disposable local _test database is required.");
  const url = new URL(value);
  if (
    !["postgres:", "postgresql:"].includes(url.protocol) ||
    !["localhost", "127.0.0.1"].includes(url.hostname) ||
    // pg accepts query parameters that override the URL's network destination.
    ["host", "hostaddr", "port", "database", "dbname"].some((key) =>
      url.searchParams.has(key),
    ) ||
    !decodeURIComponent(url.pathname.slice(1)).endsWith("_test")
  )
    throw new Error("A disposable local _test database is required.");
  return url;
}
if (databaseTestsEnabled) requireTestDatabaseUrl();

export async function createIsolatedDatabase() {
  const url = requireTestDatabaseUrl();
  const schema = `foundation_${randomUUID().replaceAll("-", "")}`;
  const client = new Client({ connectionString: url.toString() });
  await client.connect();
  try {
    await client.query(`CREATE SCHEMA "${schema}"`);
    await client.query(`SET search_path TO "${schema}"`);
    // One migration at a time: some existing migrations add enum values that
    // cannot be used until the transaction introducing them commits.
    const migrations = (await readdir("prisma/migrations"))
      .filter((name) => /^\d/.test(name))
      .sort();
    const apply = async (name: string) => {
      await client.query(
        await readFile(`prisma/migrations/${name}/migration.sql`, "utf8"),
      );
    };
    let closed = false;
    const cleanup = async () => {
      if (closed) return;
      closed = true;
      try {
        await client.query("ROLLBACK");
        await client.query("SET search_path TO public");
        await client.query(`DROP SCHEMA IF EXISTS "${schema}" CASCADE`);
      } finally {
        await client.end();
      }
    };
    url.searchParams.set("options", `-c search_path=${schema}`);
    return { client, schema, migrations, apply, cleanup, url: url.toString() };
  } catch (error) {
    try {
      await client.query(`DROP SCHEMA IF EXISTS "${schema}" CASCADE`);
    } finally {
      await client.end();
    }
    throw error;
  }
}
